// WebAssembly compilation is checked against the CSP of the world that
// compiles, the way eval() already is (CodeGenerationCheckCallbackInMainThread
// uses GetContentSecurityPolicyForCurrentWorld()). Brave's internal world has
// an empty CSP of its own (see cosmetic_filters_js_render_frame_observer.cc),
// so its scripts can compile WebAssembly on pages whose CSP forbids it, while
// page scripts keep the page's CSP. The only GetContentSecurityPolicy() call in
// the original file is the one in WasmCodeGenerationCheckCallback().
#define GetContentSecurityPolicy GetContentSecurityPolicyForCurrentWorld

#include <third_party/blink/renderer/bindings/core/v8/v8_initializer.cc>

#undef GetContentSecurityPolicy
